<?php
namespace App\Http\Controllers;
use App\Models\Section;use Illuminate\Http\{Request,RedirectResponse};use Illuminate\View\View;
class SectionController extends Controller {public function index():View{$sections=Section::withCount('students')->paginate(12);return view('sections.index',compact('sections'));}public function create():View{return view('sections.form',['section'=>new Section]);}public function store(Request $r):RedirectResponse{Section::create($this->data($r));return redirect()->route('sections.index')->with('status','Section created.');}public function edit(Section $section):View{return view('sections.form',compact('section'));}public function update(Request $r,Section $section):RedirectResponse{$section->update($this->data($r));return redirect()->route('sections.index')->with('status','Section updated.');}public function archive(Section $section):RedirectResponse{$section->update(['status'=>'archived']);return back()->with('status','Section archived.');}private function data(Request $r):array{return $r->validate(['section_name'=>'required|max:100','year_level'=>'required|in:1st,2nd,3rd,4th','program'=>'required|in:BSIT,BEED']);}}
